// src/data/commercial-claims.js
function resolveCommercialClaim({ partner = {}, venue = {} } = {}) {
  const checkedAt = partner.benefitVerifiedAt || venue.benefitVerifiedAt || null;
  const sourceUrl = partner.benefitSourceUrl || venue.benefitSourceUrl || null;
  const verified = Boolean(checkedAt && sourceUrl && /^https:\/\//i.test(sourceUrl));
  const rebatePercent = verified ? Number(partner.rebatePercent ?? venue.rebatePercent ?? 0) : 0;
  return {
    status: verified ? "verified" : "unverified",
    checkedAt,
    sourceUrl,
    rebatePercent: Number.isFinite(rebatePercent) && rebatePercent >= 0 && rebatePercent <= 100 ? rebatePercent : 0
  };
}
var benefitVerificationCopy = {
  en: (venueName) => `User benefits need verification in the official ${venueName} account`,
  "zh-Hans": (venueName) => `\u7528\u6237\u6743\u76CA\u9700\u5728 ${venueName} \u5B98\u65B9\u8D26\u6237\u5185\u6838\u9A8C`,
  "zh-Hant": (venueName) => `\u7528\u6236\u6B0A\u76CA\u9700\u5728 ${venueName} \u5B98\u65B9\u5E33\u6236\u5167\u6838\u9A57`,
  es: (venueName) => `Verifica los beneficios en la cuenta oficial de ${venueName}`,
  "pt-BR": (venueName) => `Verifique os benef\xEDcios na conta oficial da plataforma ${venueName}`,
  fr: (venueName) => `V\xE9rifiez les avantages dans le compte officiel ${venueName}`,
  de: (venueName) => `Vorteile im offiziellen ${venueName}-Konto pr\xFCfen`,
  ja: (venueName) => `${venueName} \u306E\u516C\u5F0F\u30A2\u30AB\u30A6\u30F3\u30C8\u3067\u7279\u5178\u6761\u4EF6\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044`,
  ko: (venueName) => `${venueName} \uACF5\uC2DD \uACC4\uC815\uC5D0\uC11C \uD61C\uD0DD \uC870\uAC74\uC744 \uD655\uC778\uD558\uC138\uC694`,
  ar: (venueName) => `\u062A\u062D\u0642\u0642 \u0645\u0646 \u0645\u0632\u0627\u064A\u0627 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645 \u062F\u0627\u062E\u0644 \u062D\u0633\u0627\u0628 ${venueName} \u0627\u0644\u0631\u0633\u0645\u064A`,
  tr: (venueName) => `Kullan\u0131c\u0131 avantajlar\u0131n\u0131 resmi ${venueName} hesab\u0131nda do\u011Frulay\u0131n`,
  ru: (venueName) => `\u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043F\u0440\u0435\u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u0432 \u043E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u043E\u043C \u0430\u043A\u043A\u0430\u0443\u043D\u0442\u0435 ${venueName}`,
  id: (venueName) => `Verifikasi manfaat di akun resmi ${venueName}`,
  vi: (venueName) => `Ki\u1EC3m tra quy\u1EC1n l\u1EE3i trong t\xE0i kho\u1EA3n ch\xEDnh th\u1EE9c ${venueName}`,
  it: (venueName) => `Verifica i vantaggi nell'account ufficiale ${venueName}`
};
function normalizeLocale(locale) {
  const value = String(locale || "en");
  if (value === "zh-CN" || value === "zh-SG" || value === "zh") return "zh-Hans";
  if (value === "zh-TW" || value === "zh-HK" || value === "zh-MO" || /hant/i.test(value)) return "zh-Hant";
  if (value.toLowerCase().startsWith("pt")) return "pt-BR";
  const base = value.split("-")[0];
  return benefitVerificationCopy[value] ? value : base;
}
function publicCommercialBenefit({ locale = "en", venueName = "the platform", claim } = {}) {
  if (claim?.status === "verified") return null;
  const normalizedLocale = normalizeLocale(locale);
  const copy = benefitVerificationCopy[normalizedLocale] || benefitVerificationCopy.en;
  return copy(venueName);
}

// src/data/public-cta.js
var CODE_QUERY_KEYS = ["ref", "inviteCode", "invite_code", "affiliate_id", "channelCode", "vipCode", "rcode", "reg"];
function codeFromRegistrationUrl(url) {
  try {
    const parsed = new URL(url);
    for (const key of CODE_QUERY_KEYS) {
      const value = parsed.searchParams.get(key);
      if (value) return value;
    }
    const segments = parsed.pathname.split("/").filter(Boolean);
    const joinIndex = segments.findIndex((segment) => /^(join|refer|ref)$/i.test(segment));
    if (joinIndex >= 0 && segments[joinIndex + 1]) return segments[joinIndex + 1];
  } catch {
    return null;
  }
  return null;
}
function routeInviteCode({ slug, registrationUrl, partner, venue }) {
  const configured = partner.inviteCode ?? venue.inviteCode ?? null;
  const routeCode = codeFromRegistrationUrl(registrationUrl);
  if (!routeCode) return configured;
  if (slug === "bitget") return configured || routeCode;
  return routeCode;
}
function publicCtaForVenue(slug, locale = "en") {
  const db = venueDatabase[slug] || {};
  const partner = partnerRegistry[slug] || {};
  const claim = resolveCommercialClaim({ partner, venue: db });
  const officialDomain = partner.officialDomain || db.officialDomain || "";
  const registrationUrl = partner.registrationUrl || db.registrationUrl || (officialDomain ? `https://${officialDomain}` : "#");
  const registrationUrls = [
    registrationUrl,
    ...partner.alternateRegistrationUrls || db.alternateRegistrationUrls || []
  ].filter((url, index, urls) => /^https:\/\//i.test(url || "") && urls.indexOf(url) === index);
  const hasHttpsRegistration = /^https:\/\//i.test(registrationUrl || "");
  const hasReferral = Boolean(partner.hasReferral ?? db.hasReferral);
  const hasPartnerRoute = hasReferral && hasHttpsRegistration;
  const primaryInviteCode = hasPartnerRoute ? routeInviteCode({ slug, registrationUrl, partner, venue: db }) : null;
  const isZh = String(locale).startsWith("zh");
  const configuredBenefit = isZh ? partner.benefit?.[locale] || partner.benefit?.["zh-Hans"] || db.benefit?.[locale] || db.benefit?.["zh-Hans"] || "" : partner.benefit?.[locale] || partner.benefit?.en || db.benefit?.[locale] || db.benefit?.en || "";
  const benefit = claim.status === "verified" ? configuredBenefit : publicCommercialBenefit({ locale, venueName: db.name || slug, claim });
  return {
    slug,
    name: db.name || partner.name || slug,
    // Keep the source records available to local UI gates. Callers must still
    // use the projected fields below for public copy and outbound actions.
    db,
    partner,
    officialDomain,
    registrationUrl,
    registrationUrls,
    alternateRegistrationUrls: registrationUrls.slice(1),
    inviteCode: primaryInviteCode,
    configuredInviteCode: hasPartnerRoute ? partner.inviteCode ?? db.inviteCode ?? null : null,
    hasReferral,
    hasPartnerRoute,
    routeAvailable: hasPartnerRoute,
    benefitVerified: claim.status === "verified",
    rebatePercent: claim.status === "verified" ? claim.rebatePercent : 0,
    benefit,
    claim,
    commercialClaim: claim
  };
}
function publicCtaForTopicPlatform(platform, locale = "en") {
  const cta = publicCtaForVenue(platform?.slug, locale);
  return {
    ...platform,
    affiliateUrl: cta.registrationUrl,
    hasReferral: cta.hasReferral,
    hasPartnerRoute: cta.hasPartnerRoute,
    benefitVerified: cta.benefitVerified,
    inviteCode: cta.inviteCode,
    rebate: cta.rebatePercent,
    netFee: cta.claim.status === "verified" ? platform?.netFee : String(locale).startsWith("zh") ? "\u5B98\u65B9\u8D39\u7387\u5F85\u6838\u9A8C" : "Official schedule to verify",
    benefit: cta.benefit,
    claimStatus: cta.claim.status,
    bonus: cta.claim.status === "verified" ? platform?.bonus : null
  };
}

